Page(name: "Password reset", route: Route(path: "/reset-password"))

Build(
  Scaffold(
    appBar: DumplingHouseHeader(),
    body: ScrollView(label: "Password reset", child: Column(gap: Space.md, padding: Insets(y: 12), children: [Column(gap: Space.md, padding: Insets(x: 16, y: 8), children: [
    Text(child: "Reset your password", size: FontSize.xxl, weight: FontWeight.semibold, align: TextAlign.center, lineHeight: 1.15), Box(padding: Space.md, radius: Radius.lg, background: Color.surface, shadow: Shadow.md, child: Column(gap: Space.sm, children: [Row(gap: Space.sm, children: [Icon(name: Icons.email, color: Color.primary), Expanded(child: Text(child: "We'll email you a reset link.", size: FontSize.sm, color: Color.textMuted))])])), Form(id: "resetPassword", onSubmit: ResetPreviewPassword(), child: Column(gap: Space.md, children: [TextField(name: "email", label: "Your email", type: InputType.email, required: true, background: Color.surface, border: Border(width: 1, color: Color.border), radius: Radius.lg), SubmitButton(label: "Send reset link", fullWidth: true)])), Button(label: "Back to the menu", style: ButtonStyle.ghost, icon: Icons.chevronLeft, onTap: Navigate(to: Route.menu))
  ])])),
  )
)
